def transform(grid):
    h, w = len(grid), len(grid[0])
    mark = next(v for v in {x for row in grid for x in row} if v != max({x for row in grid for x in row}, key=lambda q: sum(row.count(q) for row in grid)))
    out = [row[:] for row in grid]
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cs, cs[1:]):
            for c in range(a+1, b):
                if grid[r][c] != mark: out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rs, rs[1:]):
            for r in range(a+1, b):
                if grid[r][c] != mark: out[r][c] = 2
    return out

