def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    mark = min(counts, key=counts.get)
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        pts = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(pts, pts[1:]):
            for c in range(a+1, b):
                if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        pts = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(pts, pts[1:]):
            for r in range(a+1, b):
                if grid[r][c] == bg: out[r][c] = 2
    return out

